//! Vendored GIF files for `clazel-gif` (phase-6.md item 6.7): Wuffs'
//! `test/data/*.gif` and `test/data/artificial-gif/*.gif`.
//!
//! The files are binary, so there is nothing to translate: like the fonts'
//! converter (`fonts.rs`), this checks that each file is the one its
//! `SOURCE.md` names (a `` - `X.gif`: sha256 `…` `` line) and that it still
//! looks like a GIF89a (first six bytes `GIF89a`), and writes a table that
//! embeds it with `include_bytes!`. No GIF block is parsed here: that is
//! the crate's job, and the differential test's.

use std::fmt::Write as _;
use std::path::Path;

use sha2::{Digest, Sha256};

use super::fonts::listed_hash;
use super::hash::to_hex;

/// `tests/data/wuffs-gif/`: Wuffs' `test/data/*.gif`.
pub const FILES_MAIN: &[&str] = &[
    "animated-red-blue.gif",
    "bricks-dither.gif",
    "bricks-gray.gif",
    "bricks-nodither.gif",
    "gifplayer-muybridge.gif",
    "harvesters.gif",
    "hat.gif",
    "hibiscus.primitive.gif",
    "hibiscus.regular.gif",
    "hippopotamus.interlaced.gif",
    "hippopotamus.interlaced.truncated.gif",
    "hippopotamus.masked-with-muybridge.gif",
    "hippopotamus.regular.gif",
    "muybridge.gif",
    "pjw-thumbnail.gif",
    "transparent-1x1.gif",
];

/// `tests/data/wuffs-gif-artificial/`: Wuffs' `test/data/artificial-gif/*.gif`.
pub const FILES_ARTIFICIAL: &[&str] = &[
    "background-color.gif",
    "empty-palette.gif",
    "frame-out-of-bounds.gif",
    "metadata-empty.gif",
    "metadata-full.gif",
    "multiple-graphic-controls.gif",
    "multiple-loop-counts.gif",
    "no-frames.gif",
    "pixel-data-none.gif",
    "pixel-data-not-enough.gif",
    "pixel-data-too-much-bad-lzw.gif",
    "pixel-data-too-much-good-lzw.gif",
    "small-frame-interlaced.gif",
    "transparent-index.gif",
    "zero-width-frame.gif",
];

/// The files of the suite in `dir`, by its name.
fn files_of(name: &str) -> Result<&'static [&'static str], String> {
    match name {
        "wuffs-gif" => Ok(FILES_MAIN),
        "wuffs-gif-artificial" => Ok(FILES_ARTIFICIAL),
        _ => Err(format!("no GIF list for suite {name:?}")),
    }
}

/// Check the suite in `dir` and write its table.
pub fn convert(dir: &Path) -> Result<String, String> {
    let name = dir
        .file_name()
        .and_then(|n| n.to_str())
        .ok_or_else(|| format!("{}: no directory name", dir.display()))?;
    let files = files_of(name)?;
    let source =
        std::fs::read_to_string(dir.join("SOURCE.md")).map_err(|e| format!("SOURCE.md: {e}"))?;
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// Generated by `cargo xtask testdata` from `tests/data/{name}/` \
         (xtask/src/testdata/wuffs_gif.rs). Do not edit.\n\
         \n\
         /// One vendored GIF file, checked against `SOURCE.md` when generated.\n\
         pub struct Case {{\n    \
             /// The file's name in `tests/data/{name}/`.\n    \
             pub file: &'static str,\n    \
             /// Its SHA-256, as `SOURCE.md` lists it.\n    \
             pub sha256: &'static str,\n    \
             /// Its bytes.\n    \
             pub bytes: &'static [u8],\n\
         }}\n\
         \n\
         /// Every file of the suite.\n\
         pub const FILES: &[Case] = &["
    );
    for file in files {
        let bytes = std::fs::read(dir.join(file)).map_err(|e| format!("{file}: {e}"))?;
        let hash = to_hex(&Sha256::digest(&bytes));
        let listed = listed_hash(&source, file)?;
        if hash != listed {
            return Err(format!(
                "{file}: SHA-256 {hash} differs from SOURCE.md's {listed}"
            ));
        }
        if !bytes.starts_with(b"GIF89a") {
            return Err(format!("{file}: does not start with `GIF89a`"));
        }
        let _ = writeln!(
            out,
            "    Case {{\n        \
                 file: {file:?},\n        \
                 sha256: {hash:?},\n        \
                 bytes: include_bytes!(\"../data/{name}/{file}\"),\n    \
             }},"
        );
    }
    out.push_str("];\n");
    Ok(out)
}
